+static void sdnand_fill_pattern(FAR uint8_t *buffer, unsigned int pattern)
+{
+  uint32_t state = 0x7258a5c3;
+  size_t i;
+
+  for (i = 0; i < SDNAND_SECTOR_SIZE; i++)
+    {
+      switch (pattern)
+        {
+          case 0:
+            buffer[i] = 0x00;
+            break;
+          case 1:
+            buffer[i] = 0xff;
+            break;
+          case 2:
+            buffer[i] = (i & 1) == 0 ? 0x55 : 0xaa;
+            break;
+          default:
+            state = state * 1664525u + 1013904223u;
+            buffer[i] = state >> 24;
+            break;
+        }
+    }
+}
