+static int sdnand_raw_test(bool restore)
+{
+  uint8_t storage[SDNAND_SECTOR_SIZE * 3 + 2];
+  FAR uint8_t *original = storage;
+  FAR uint8_t *pattern = storage + SDNAND_SECTOR_SIZE + 1;
+  FAR uint8_t *readback = storage + SDNAND_SECTOR_SIZE * 2 + 2;
+  FAR struct inode *inode;
+  struct geometry geo;
+  blkcnt_t sector;
+  unsigned int pass;
+  ssize_t nsectors;
+  int ret;
+
+  ret = open_blockdriver("/dev/mmcsd0", 0, &inode);
