+static bool bk7258_block_exists(FAR const char *path)
+{
+  FAR struct inode *inode;
+  int ret;
+
+  ret = open_blockdriver(path, 0, &inode);
+  if (ret < 0)
+    {
+      return false;
+    }
+
+  close_blockdriver(inode);
+  return true;
+}
