+int bk7258_mmcsd_mount(FAR const char *source)
+{
+  int ret;
+
+  ret = nxmutex_lock(&g_mmcsd_lock);
+  if (ret < 0)
+    {
+      return ret;
+    }
+
+  if (g_mmcsd_state != BK7258_MMCSD_COMPLETE ||
+      !bk7258_block_exists("/dev/mmcsd0"))
+    {
