 static int bk7258_mmcsd_probe(void)
 {
   FAR struct sdio_dev_s *dev;
   FAR struct inode *inode;
   int ret;

   dev = bk7258_sdio_initialize(0);
   if (dev == NULL)
     {
       printf("SDIO initialize failed\n");
       return -ENODEV;
