+             ret);
+    }
+#endif
+
   return OK;
 }

 int bk7258_mmcsd_initialize(void)
 {
   FAR struct inode *inode;
   int ret;

   ret = nxmutex_lock(&g_mmcsd_lock);
   if (ret < 0)
     {
       return ret;
     }

   if (g_mmcsd_state == BK7258_MMCSD_COMPLETE)
     {
