+#ifdef CONFIG_BK7258_SDNAND_AUTOMOUNT
+          if (!g_mmcsd_mounted)
+            {
+              ret = bk7258_mmcsd_mount_locked(NULL);
+            }
+#endif
         }
       else
         {
           ret = g_mmcsd_result;
         }

       nxmutex_unlock(&g_mmcsd_lock);
       return ret;
     }

   g_mmcsd_state = BK7258_MMCSD_RUNNING;
   ret = bk7258_mmcsd_probe();
   g_mmcsd_result = ret;
   g_mmcsd_state = BK7258_MMCSD_COMPLETE;
   nxmutex_unlock(&g_mmcsd_lock);
   return ret;
 }

