+  if (!g_mmcsd_mounted)
+    {
+      nxmutex_unlock(&g_mmcsd_lock);
+      return OK;
+    }
+
+  ret = nx_umount2(CONFIG_BK7258_SDNAND_MOUNTPOINT, 0);
+  if (ret == OK)
+    {
+      g_mmcsd_mounted = false;
+      g_mount_source[0] = '\0';
