 struct bk7258_sdio_s
 {
   struct sdio_dev_s dev;
   uint32_t blocklen;
   uint32_t nblocks;
   FAR uint8_t *buffer;
+  FAR const uint8_t *tx_buffer;
   size_t remaining;
   sdio_eventset_t wait_events;
   sdio_eventset_t wake_events;
   uint32_t wait_timeout;
   uint32_t clock_code;
   uint32_t irq_status;
   uint32_t last_cmd;
