+                     BK7258_SDIO_DATA_TIMEOUT |
+                     BK7258_SDIO_RX_NEED_READ |
+                     BK7258_SDIO_TX_NEED_WRITE |
+                     BK7258_SDIO_TX_FIFO_EMPTY |
+                     BK7258_SDIO_DATA_CRC_OK |
+                     BK7258_SDIO_DATA_CRC_FAIL);

