         }
       else
         {
           priv->data_result = OK;
         }

       priv->data_active = false;
       if (clear != 0)
         {
           sdio_write(BK7258_SDIO_INT_STATUS, clear);
         }

       nxsem_post(&priv->data_sem);
     }
   else if (clear != 0)
     {
       sdio_write(BK7258_SDIO_INT_STATUS, clear);
     }

